using System;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[Serializable]
public class StartingEffect
{
	[SerializeField]
	[AllowNesting]
	private Effect effect;

	[SerializeField]
	[AllowNesting]
	private int effectAmount;

	public Effect Effect => effect;

	public int EffectAmount => effectAmount;

	public StartingEffect(StartingEffect startingEffect)
	{
		effect = startingEffect.Effect;
		effectAmount = startingEffect.EffectAmount;
	}

	public StartingEffect(Effect effect, int effectAmount)
	{
		if (effect != null)
		{
			this.effect = effect;
		}
		this.effectAmount = effectAmount;
	}

	public void ModifyEffectAmount(int amount)
	{
		effectAmount = amount;
	}

	public void IncreaseEffectAmount(int amount)
	{
		effectAmount += amount;
		if (effectAmount >= EffectsValues.INFINITY)
		{
			effectAmount = EffectsValues.INFINITY;
		}
	}
}
